import { useParams } from "react-router-dom";
import { useRef } from "react";

import projects from "../data/projects";

import useTooltip from "../hooks/useTooltip";

import Navbar from "../components/navigation/Navbar";
import Footer from "../components/footer/Footer";

import { Link } from "react-router-dom";

const ProjectPage = () => {
  const { slug } = useParams();
  const project = projects.find((item) => item.slug === slug);
  const project_container = projects.filter((item) => item.slug !== slug);
  const imgRef = useRef(null);
  const { tooltip, pos, showTooltip, moveTooltip, hideTooltip } = useTooltip();
  if (!project) {
    return <h1>Project Not Found</h1>;
  }
  return (
    <>
      <Navbar/>
      <section className="Project_Page">
        <div className="Project_Page_Top">
          <h3 className="text-body-lg">{project.title}</h3>
          <p className="text-body-lg">{project.type}</p>
          <div className="Project_Page_Image">
            <img
              ref={imgRef}
              src={project.image}
              alt={project.title}
              crossOrigin="anonymous"
              loading="lazy"
              onMouseEnter={(e) => showTooltip(e, imgRef, project.title)}
              onMouseMove={moveTooltip}
              onMouseLeave={hideTooltip}
            />
            {tooltip && (
              <div
                className="projects__tooltip"
                style={{
                  backgroundColor: tooltip.bg,
                  color: tooltip.color,
                  top: pos.y + 16,
                  left: pos.x + 16,
                }}
              >
                {tooltip.text}
              </div>
            )}
          </div>
        </div>
        <div className="Project_Page_Bottom">
          <p className="text-body">{project.detail}</p>
          {project.link_to ? (
            <a
              className="text-body-lg"
              href={project.link_to.url}
              target="_blank"
              rel="noopener noreferrer"
              onMouseEnter={(e) => showTooltip(e, null, "Link")}
              onMouseMove={moveTooltip}
              onMouseLeave={hideTooltip}
            >
              {project.link_to.type}
            </a>
          ) : (
            <p className="text-body-lg">{project.type}</p>
          )}
        </div>
      </section>
      <section className="container_main">
        {project_container.map((element, index) => (
          <div key={index}>
            <img src={element.image} alt={element.title} />
            <div className="container_between">
              <div className="container_left">
                <p>{element.title}</p>
                <p>{element.with}</p>
              </div>
              <div className="container_right">
                <Link to={`/projects/${element.slug}`}>
                  <svg width="13" height="11" viewBox="0 0 13 11" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <g clipPath="url(#clip0_96_158)">
                      <path d="M12.7432 4.11621V6.68066L7.20996 10.7549V8.89355L10.9619 6.12891L0.000976562 6.12988L0 4.62988L10.917 4.62891L7.20996 1.87012V0L12.7432 4.11621Z" fill="white"/>
                    </g>
                    <defs>
                      <clipPath id="clip0_96_158">
                        <rect width="13" height="11" fill="white"/>
                      </clipPath>
                    </defs>
                  </svg>
                </Link>
              </div>
            </div>
          </div>
        ))}
      </section>
      <Footer/>
    </>
  );
};

export default ProjectPage;
